    async def search_chat_messages(
        self,
        *,
        chat_id: int = 0,
        topic_id: MessageTopic | None = None,
        query: str = "",
        sender_id: MessageSender | None = None,
        from_message_id: int = 0,
        offset: int = 0,
        limit: int = 0,
        filter: SearchMessagesFilter | None = None,
    ) -> FoundChatMessages:
        """Searches for messages with given words in the chat. Returns the results in reverse
        chronological order, i.e. in order of decreasing message_id. Cannot be used in
        secret chats with a non-empty query (searchSecretMessages must be used instead), or
        without an enabled message database. For optimal performance, the number of returned
        messages is chosen by TDLib and can be smaller than the specified limit. A
        combination of query, sender_id, filter and topic_id search criteria is expected to
        be supported, only if it is required for Telegram official application
        implementation

        Args:
            chat_id: Identifier of the chat in which to search messages
            topic_id: Pass topic identifier to search messages only in specific topic; pass
                null to search for messages in all topics
            query: Query to search for
            sender_id: Identifier of the sender of messages to search for; pass null to
                search for messages from any sender. Not supported in secret chats
            from_message_id: Identifier of the message starting from which history must be
                fetched; use 0 to get results from the last message
            offset: Specify 0 to get results from exactly the message from_message_id or a
                negative number to get the specified message and some newer messages
            limit: The maximum number of messages to be returned; must be positive and can't
                be greater than 100. If the offset is negative, then the limit must be
                greater than -offset. For optimal performance, the number of returned
                messages is chosen by TDLib and can be smaller than the specified limit
            filter: Additional filter for messages to search; pass null to search for all
                messages

        Returns:
            FoundChatMessages: Searches for messages with given words in the chat. Returns
                the results in reverse chronological order, i.e. in order of decreasing
                message_id. Cannot be used in secret chats with a non-empty query
                (searchSecretMessages must be used instead), or without an enabled message
                database. For optimal performance, the number of returned messages is chosen
                by TDLib and can be smaller than the specified limit. A combination of
                query, sender_id, filter and topic_id search criteria is expected to be
                supported, only if it is required for Telegram official application
                implementation
        """
        request = functions.SearchChatMessages(
            chat_id=chat_id,
            topic_id=topic_id,
            query=query,
            sender_id=sender_id,
            from_message_id=from_message_id,
            offset=offset,
            limit=limit,
            filter=filter,
        )
        result: FoundChatMessages = await self._call(request, FoundChatMessages)
        return result

    async def search_messages(
        self,
        *,
        chat_list: ChatList | None = None,
        query: str = "",
        offset: str = "",
        limit: int = 0,
        filter: SearchMessagesFilter | None = None,
        chat_type_filter: SearchMessagesChatTypeFilter | None = None,
        min_date: int = 0,
        max_date: int = 0,
    ) -> FoundMessages:
        """Searches for messages in all chats except secret chats. Returns the results in
        reverse chronological order (i.e., in order of decreasing (date, chat_id,
        message_id)). For optimal performance, the number of returned messages is chosen by
        TDLib and can be smaller than the specified limit

        Args:
            chat_list: Chat list in which to search messages; pass null to search in all
                chats regardless of their chat list. Only Main and Archive chat lists are
                supported
            query: Query to search for
            offset: Offset of the first entry to return as received from the previous
                request; use empty string to get the first chunk of results
            limit: The maximum number of messages to be returned; up to 100. For optimal
                performance, the number of returned messages is chosen by TDLib and can be
                smaller than the specified limit
            filter: Additional filter for messages to search; pass null to search for all
                messages. Filters searchMessagesFilterMention,
                searchMessagesFilterUnreadMention, searchMessagesFilterUnreadReaction,
                searchMessagesFilterUnreadPollVote, searchMessagesFilterFailedToSend, and
                searchMessagesFilterPinned are unsupported in this function
            chat_type_filter: Additional filter for type of the chat of the searched
                messages; pass null to search for messages in all chats
            min_date: If not 0, the minimum date of the messages to return
            max_date: If not 0, the maximum date of the messages to return

        Returns:
            FoundMessages: Searches for messages in all chats except secret chats. Returns
                the results in reverse chronological order (i.e., in order of decreasing
                (date, chat_id, message_id)). For optimal performance, the number of
                returned messages is chosen by TDLib and can be smaller than the specified
                limit
        """
        request = functions.SearchMessages(
            chat_list=chat_list,
            query=query,
            offset=offset,
            limit=limit,
            filter=filter,
            chat_type_filter=chat_type_filter,
            min_date=min_date,
            max_date=max_date,
        )
        result: FoundMessages = await self._call(request, FoundMessages)
        return result

