    async def click_chat_sponsored_message(
        self,
        *,
        chat_id: int = 0,
        message_id: int = 0,
        is_media_click: bool = False,
        from_fullscreen: bool = False,
    ) -> Ok:
        """Informs TDLib that the user opened the sponsored chat via the button, the name, the
        chat photo, a mention in the sponsored message text, or the media in the sponsored
        message

        Args:
            chat_id: Chat identifier of the sponsored message
            message_id: Identifier of the sponsored message
            is_media_click: Pass true if the media was clicked in the sponsored message
            from_fullscreen: Pass true if the user expanded the video from the sponsored
                message fullscreen before the click

        Returns:
            Ok: Informs TDLib that the user opened the sponsored chat via the button, the
                name, the chat photo, a mention in the sponsored message text, or the media
                in the sponsored message
        """
