    async def get_message_link(
        self,
        *,
        chat_id: int = 0,
        message_id: int = 0,
        media_timestamp: int = 0,
        checklist_task_id: int = 0,
        poll_option_id: str = "",
        for_album: bool = False,
        in_message_thread: bool = False,
    ) -> MessageLink:
        """Returns an HTTPS link to a message in a chat. Available only if
        messageProperties.can_get_link, or if
        messageProperties.can_get_media_timestamp_links and a media timestamp link is
        generated. This is an offline method

        Args:
            chat_id: Identifier of the chat to which the message belongs
            message_id: Identifier of the message
            media_timestamp: If not 0, timestamp from which the video/audio/video note/voice
                note/story playing must start, in seconds. The media can be in the message
                content or in its link preview
            checklist_task_id: If not 0, identifier of the checklist task in the message to
                be linked
            poll_option_id: If not empty, identifier of the poll option in the message to be
                linked
            for_album: Pass true to create a link for the whole media album
            in_message_thread: Pass true to create a link to the message as a channel post
                comment, in a message thread, or a forum topic

        Returns:
            MessageLink: Returns an HTTPS link to a message in a chat. Available only if
                messageProperties.can_get_link, or if
                messageProperties.can_get_media_timestamp_links and a media timestamp link
                is generated. This is an offline method
        """
        request = functions.GetMessageLink(
            chat_id=chat_id,
            message_id=message_id,
            media_timestamp=media_timestamp,
            checklist_task_id=checklist_task_id,
            poll_option_id=poll_option_id,
            for_album=for_album,
            in_message_thread=in_message_thread,
        )
        result: MessageLink = await self._call(request, MessageLink)
        return result

