    async def translate_text(
        self,
        *,
        text: FormattedText,
        to_language_code: str = "",
        tone: str = "",
    ) -> FormattedText:
        """Translates a text to the given language; must not be used in secret chats. If the
        current user is a Telegram Premium user, then text formatting is preserved

        Args:
            text: Text to translate
            to_language_code: Language code of the language to which the message is
                translated. Must be one of "af", "sq", "am", "ar", "hy", "az", "eu", "be",
                "bn", "bs", "bg", "ca", "ceb", "zh-CN", "zh", "zh-Hans", "zh-TW", "zh-Hant",
                "co", "hr", "cs", "da", "nl", "en", "eo", "et", "fi", "fr", "fy", "gl",
                "ka", "de", "el", "gu", "ht", "ha", "haw", "he", "iw", "hi", "hmn", "hu",
                "is", "ig", "id", "in", "ga", "it", "ja", "jv", "kn", "kk", "km", "rw",
                "ko", "ku", "ky", "lo", "la", "lv", "lt", "lb", "mk", "mg", "ms", "ml",
                "mt", "mi", "mr", "mn", "my", "ne", "no", "ny", "or", "ps", "fa", "pl",
                "pt", "pt-BR", "pa", "ro", "ru", "sm", "gd", "sr", "st", "sn", "sd", "si",
                "sk", "sl", "so", "es", "su", "sw", "sv", "tl", "tg", "ta", "tt", "te",
                "th", "tr", "tk", "uk", "ur", "ug", "uz", "vi", "cy", "xh", "yi", "ji",
                "yo", "zu"
            tone: Tone of the translation; must be one of "", "formal", "neutral", "casual";
                defaults to "neutral"

        Returns:
            FormattedText: Translates a text to the given language; must not be used in
                secret chats. If the current user is a Telegram Premium user, then text
                formatting is preserved
        """
        request = functions.TranslateText(
            text=text,
            to_language_code=to_language_code,
            tone=tone,
        )
        result: FormattedText = await self._call(request, FormattedText)
        return result

