    async def compose_text_with_ai(
        self,
        *,
        text: FormattedText,
        translate_to_language_code: str = "",
        style_name: str = "",
        add_emojis: bool = False,
    ) -> FormattedText:
        """Changes text using an AI model; must not be used in secret chats. May return an
        error with a message "AICOMPOSE_FLOOD_PREMIUM" if Telegram Premium is required to
        send further requests

        Args:
            text: The original text
            translate_to_language_code: Pass a language code to which the text will be
                translated; pass an empty string if translation isn't needed. See
                translateText.to_language_code for the list of supported values
            style_name: Name of the style of the resulted text; handle
                updateTextCompositionStyles to get the list of supported styles; pass an
                empty string to keep the current style of the text
            add_emojis: Pass true to add emoji to the text

        Returns:
            FormattedText: Changes text using an AI model; must not be used in secret chats.
                May return an error with a message "AICOMPOSE_FLOOD_PREMIUM" if Telegram
                Premium is required to send further requests
        """
        request = functions.ComposeTextWithAi(
            text=text,
            translate_to_language_code=translate_to_language_code,
            style_name=style_name,
            add_emojis=add_emojis,
        )
        result: FormattedText = await self._call(request, FormattedText)
        return result

