    async def resend_messages(
        self,
        *,
        chat_id: int = 0,
        message_ids: list[int] | None = None,
        quote: InputTextQuote | None = None,
        paid_message_star_count: int = 0,
    ) -> Messages:
        """Resends messages which failed to send. Can be called only for messages for which
        messageSendingStateFailed.can_retry is true and after specified in
        messageSendingStateFailed.retry_after time passed. If a message is re-sent, the
        corresponding failed to send message is deleted. Returns the sent messages in the
        same order as the message identifiers passed in message_ids. If a message can't be
        re-sent, null will be returned instead of the message

        Args:
            chat_id: Identifier of the chat to send messages
            message_ids: Identifiers of the messages to resend. Message identifiers must be
                in a strictly increasing order
            quote: New manually chosen quote from the message to be replied; pass null if
                none. Ignored if more than one message is re-sent, or if
                messageSendingStateFailed.need_another_reply_quote == false
            paid_message_star_count: The number of Telegram Stars the user agreed to pay to
                send the messages. Ignored if
                messageSendingStateFailed.required_paid_message_star_count == 0

        Returns:
            Messages: Resends messages which failed to send. Can be called only for messages
                for which messageSendingStateFailed.can_retry is true and after specified in
                messageSendingStateFailed.retry_after time passed. If a message is re-sent,
                the corresponding failed to send message is deleted. Returns the sent
                messages in the same order as the message identifiers passed in message_ids.
                If a message can't be re-sent, null will be returned instead of the message
        """
        request = functions.ResendMessages(
            chat_id=chat_id,
            message_ids=message_ids or [],
            quote=quote,
            paid_message_star_count=paid_message_star_count,
        )
        result: Messages = await self._call(request, Messages)
        return result

    async def send_ephemeral_message(
        self,
        *,
        chat_id: int = 0,
        topic_id: MessageTopic | None = None,
        receiver_user_id: int = 0,
        callback_query_id: Int64 = Int64(0),
        replace_callback_query_message: bool = False,
        reply_to: InputMessageReplyTo | None = None,
        protect_content: bool = False,
        sending_id: int = 0,
        only_preview: bool = False,
        reply_markup: ReplyMarkup | None = None,
        input_message_content: InputMessageContent,
    ) -> Message:
        """Sends an ephemeral message which will be received only by one bot in a chat.
        Currently, only ephemeral bot commands and replies to bot ephemeral messages can be
        sent using the method. The message is persistent across application restarts only if
        the message database is used. Returns the sent message

        Args:
            chat_id: Target chat
            topic_id: Topic in which the message will be sent; pass null if none
            receiver_user_id: Identifier of the user who will receive the message
            callback_query_id: Identifier of the callback query which triggered the message;
                for bots only
            replace_callback_query_message: Pass true if the ephemeral message must replace
                the message from which the callback query originated; for bots only
            reply_to: Information about the message to be replied; pass null if none. The
                message can be an incoming ephemeral message
            protect_content: Pass true if the content of the message must be protected from
                forwarding and saving; for bots only
            sending_id: Non-persistent identifier, which will be returned back in
                messageSendingStatePending object and can be used to match sent messages and
                corresponding updateNewMessage updates
            only_preview: Pass true to get a fake message instead of actually sending them
            reply_markup: Markup for replying to the message; pass null if none; for bots
                only
            input_message_content: The content of the message to be sent. Must be one of the
                following types: inputMessageText, inputMessageAnimation, inputMessageAudio,
                inputMessageDocument, inputMessagePhoto, inputMessageRichMessage,
                inputMessageSticker, inputMessageVideo, inputMessageVideoNote,
                inputMessageVoiceNote, inputMessageLocation, inputMessageVenue,
                inputMessageContact

        Returns:
            Message: Sends an ephemeral message which will be received only by one bot in a
                chat. Currently, only ephemeral bot commands and replies to bot ephemeral
                messages can be sent using the method. The message is persistent across
                application restarts only if the message database is used. Returns the sent
                message
        """
        request = functions.SendEphemeralMessage(
            chat_id=chat_id,
            topic_id=topic_id,
            receiver_user_id=receiver_user_id,
            callback_query_id=callback_query_id,
            replace_callback_query_message=replace_callback_query_message,
            reply_to=reply_to,
            protect_content=protect_content,
            sending_id=sending_id,
            only_preview=only_preview,
            reply_markup=reply_markup,
            input_message_content=input_message_content,
        )
        result: Message = await self._call(request, Message)
        return result

