    async def get_forum_topics(
        self,
        *,
        chat_id: int = 0,
        query: str = "",
        offset_date: int = 0,
        offset_message_id: int = 0,
        offset_forum_topic_id: int = 0,
        limit: int = 0,
    ) -> ForumTopics:
        """Returns found forum topics in a forum supergroup chat or a chat with a bot with
        topics. This is a temporary method for getting information about topic list from the
        server

        Args:
            chat_id: Identifier of the chat
            query: Query to search for in the forum topic's name
            offset_date: The date starting from which the results need to be fetched. Use 0
                or any date in the future to get results from the last topic
            offset_message_id: The message identifier of the last message in the last found
                topic, or 0 for the first request
            offset_forum_topic_id: The forum topic identifier of the last found topic, or 0
                for the first request
            limit: The maximum number of forum topics to be returned; up to 100. For optimal
                performance, the number of returned forum topics is chosen by TDLib and can
                be smaller than the specified limit

        Returns:
            ForumTopics: Returns found forum topics in a forum supergroup chat or a chat
                with a bot with topics. This is a temporary method for getting information
                about topic list from the server
        """
        request = functions.GetForumTopics(
            chat_id=chat_id,
            query=query,
            offset_date=offset_date,
            offset_message_id=offset_message_id,
            offset_forum_topic_id=offset_forum_topic_id,
            limit=limit,
        )
        result: ForumTopics = await self._call(request, ForumTopics)
        return result

