    async def open_web_app(
        self,
        *,
        chat_id: int = 0,
        bot_user_id: int = 0,
        url: str = "",
        topic_id: MessageTopic | None = None,
        reply_to: InputMessageReplyTo | None = None,
        parameters: WebAppOpenParameters,
    ) -> WebAppInfo:
        """Informs TDLib that a Web App is being opened from the attachment menu, a
        botMenuButton button, an internalLinkTypeAttachmentMenuBot link, or an
        inlineKeyboardButtonTypeWebApp button. For each bot, a confirmation alert about data
        sent to the bot must be shown once

        Args:
            chat_id: Identifier of the chat in which the Web App is opened. The Web App
                can't be opened in secret chats
            bot_user_id: Identifier of the bot, providing the Web App. If the bot is
                restricted for the current user, then show an error instead of calling the
                method
            url: The URL from an inlineKeyboardButtonTypeWebApp button, a botMenuButton
                button, an internalLinkTypeAttachmentMenuBot link, or an empty string
                otherwise
            topic_id: Topic in which the message will be sent; pass null if none
            reply_to: Information about the message or story to be replied in the message
                sent by the Web App; pass null if none
            parameters: Parameters to use to open the Web App

        Returns:
            WebAppInfo: Informs TDLib that a Web App is being opened from the attachment
                menu, a botMenuButton button, an internalLinkTypeAttachmentMenuBot link, or
                an inlineKeyboardButtonTypeWebApp button. For each bot, a confirmation alert
                about data sent to the bot must be shown once
        """
        request = functions.OpenWebApp(
            chat_id=chat_id,
            bot_user_id=bot_user_id,
            url=url,
            topic_id=topic_id,
            reply_to=reply_to,
            parameters=parameters,
        )
        result: WebAppInfo = await self._call(request, WebAppInfo)
        return result

