    async def view_messages(
        self,
        *,
        chat_id: int = 0,
        message_ids: list[int] | None = None,
        source: MessageSource | None = None,
        force_read: bool = False,
    ) -> Ok:
        """Informs TDLib that messages are being viewed by the user. Sponsored messages must be
        marked as viewed only when the entire text of the message is shown on the screen
        (excluding the button). Many useful activities depend on whether the messages are
        currently being viewed or not (e.g., marking messages as read, incrementing a view
        counter, updating a view counter, removing deleted messages in supergroups and
        channels)

        Args:
            chat_id: Chat identifier
            message_ids: The identifiers of the messages being viewed
            source: Source of the message view; pass null to guess the source based on chat
                open state
            force_read: Pass true to mark as read the specified messages even if the chat is
                closed

        Returns:
            Ok: Informs TDLib that messages are being viewed by the user. Sponsored messages
                must be marked as viewed only when the entire text of the message is shown
                on the screen (excluding the button). Many useful activities depend on
                whether the messages are currently being viewed or not (e.g., marking
                messages as read, incrementing a view counter, updating a view counter,
                removing deleted messages in supergroups and channels)
        """
        request = functions.ViewMessages(
            chat_id=chat_id,
            message_ids=message_ids or [],
            source=source,
            force_read=force_read,
        )
        result: Ok = await self._call(request, Ok)
        return result

