    async def send_message_view_metrics(
        self,
        *,
        chat_id: int = 0,
        message_id: int = 0,
        time_in_view_ms: int = 0,
        active_time_in_view_ms: int = 0,
        height_to_viewport_ratio_per_mille: int = 0,
        seen_range_ratio_per_mille: int = 0,
    ) -> Ok:
        """Informs TDLib about details of a message view by the user from a chat, a message
        thread or a forum topic history. The method must be called if the message wasn't
        seen for more than 300 milliseconds, the viewport was destroyed, or the total view
        duration exceeded 5 minutes

        Args:
            chat_id: Chat identifier
            message_id: The identifier of the message being viewed
            time_in_view_ms: The amount of time the message was seen by at least 1 pixel; in
                milliseconds
            active_time_in_view_ms: The amount of time the message was seen by at least 1
                pixel within 15 seconds after any action from the user; in milliseconds
            height_to_viewport_ratio_per_mille: The ratio of the post height to the viewport
                height in 1/1000 fractions
            seen_range_ratio_per_mille: The ratio of the viewed post height to the full post
                height in 1/1000 fractions; 0-1000

        Returns:
            Ok: Informs TDLib about details of a message view by the user from a chat, a
                message thread or a forum topic history. The method must be called if the
                message wasn't seen for more than 300 milliseconds, the viewport was
                destroyed, or the total view duration exceeded 5 minutes
        """
        request = functions.SendMessageViewMetrics(
            chat_id=chat_id,
            message_id=message_id,
            time_in_view_ms=time_in_view_ms,
            active_time_in_view_ms=active_time_in_view_ms,
            height_to_viewport_ratio_per_mille=height_to_viewport_ratio_per_mille,
            seen_range_ratio_per_mille=seen_range_ratio_per_mille,
        )
        result: Ok = await self._call(request, Ok)
        return result

