    async def ban_chat_member(
        self,
        *,
        chat_id: int = 0,
        member_id: MessageSender,
        banned_until_date: int = 0,
        revoke_messages: bool = False,
    ) -> Ok:
        """Bans a member in a chat; requires can_restrict_members administrator right. Members
        can't be banned in private or secret chats. In supergroups and channels, the user
        will not be able to return to the group on their own using invite links, etc.,
        unless unbanned first

        Args:
            chat_id: Chat identifier
            member_id: Member identifier
            banned_until_date: Point in time (Unix timestamp) when the user will be
                unbanned; 0 if never. If the user is banned for more than 366 days or for
                less than 30 seconds from the current time, the user is considered to be
                banned forever. Ignored in basic groups and if a chat is banned
            revoke_messages: Pass true to delete all messages in the chat for the user who
                is being removed. Always true for supergroups and channels

        Returns:
            Ok: Bans a member in a chat; requires can_restrict_members administrator right.
                Members can't be banned in private or secret chats. In supergroups and
                channels, the user will not be able to return to the group on their own
                using invite links, etc., unless unbanned first
        """
        request = functions.BanChatMember(
            chat_id=chat_id,
            member_id=member_id,
            banned_until_date=banned_until_date,
            revoke_messages=revoke_messages,
        )
        result: Ok = await self._call(request, Ok)
        return result

