    async def add_file_to_downloads(
        self,
        *,
        file_id: int = 0,
        chat_id: int = 0,
        message_id: int = 0,
        priority: int = 0,
    ) -> File:
        """Adds a file from a message to the list of file downloads. Download progress and
        completion of the download will be notified through updateFile updates. If message
        database is used, the list of file downloads is persistent across application
        restarts. The downloading is independent of download using downloadFile, i.e. it
        continues if downloadFile is canceled or is used to download a part of the file

        Args:
            file_id: Identifier of the file to download
            chat_id: Chat identifier of the message with the file
            message_id: Message identifier
            priority: Priority of the download (1-32). The higher the priority, the earlier
                the file will be downloaded. If the priorities of two files are equal, then
                the last one for which downloadFile/addFileToDownloads was called will be
                downloaded first

        Returns:
            File: Adds a file from a message to the list of file downloads. Download
                progress and completion of the download will be notified through updateFile
                updates. If message database is used, the list of file downloads is
                persistent across application restarts. The downloading is independent of
                download using downloadFile, i.e. it continues if downloadFile is canceled
                or is used to download a part of the file
        """
        request = functions.AddFileToDownloads(
            file_id=file_id,
            chat_id=chat_id,
            message_id=message_id,
            priority=priority,
        )
        result: File = await self._call(request, File)
        return result

