    async def add_recent_sticker(
        self,
        *,
        is_attached: bool = False,
        sticker: InputFile,
    ) -> Stickers:
        """Manually adds a new sticker to the list of recently used stickers. The new sticker
        is added to the top of the list. If the sticker was already in the list, it is
        removed from the list first. Only stickers belonging to a sticker set or in WEBP or
        WEBM format can be added to this list. Emoji stickers can't be added to recent
        stickers

        Args:
            is_attached: Pass true to add the sticker to the list of stickers recently
                attached to photo or video files; pass false to add the sticker to the list
                of recently sent stickers
            sticker: Sticker file to add

        Returns:
            Stickers: Manually adds a new sticker to the list of recently used stickers. The
                new sticker is added to the top of the list. If the sticker was already in
                the list, it is removed from the list first. Only stickers belonging to a
                sticker set or in WEBP or WEBM format can be added to this list. Emoji
                stickers can't be added to recent stickers
        """
        request = functions.AddRecentSticker(
            is_attached=is_attached,
            sticker=sticker,
        )
        result: Stickers = await self._call(request, Stickers)
        return result

