    async def create_bot(
        self,
        *,
        manager_bot_user_id: int = 0,
        name: str = "",
        username: str = "",
        via_link: bool = False,
    ) -> User:
        """Creates a bot which will be managed by another bot. Returns the created bot. May
        return an error with a message "BOT_CREATE_LIMIT_EXCEEDED" if the user already owns
        the maximum allowed number of bots as per getOption("owned_bot_count_max"). An
        internal link "https://t.me/BotFather?start=deletebot" can be processed to handle
        the error

        Args:
            manager_bot_user_id: Identifier of the bot that will manage the created bot
            name: Name of the bot; 1-64 characters
            username: Username of the bot. The username must end with "bot". Use
                checkBotUsername to find whether the name is suitable
            via_link: Pass true if the bot is created from an
                internalLinkTypeRequestManagedBot link

        Returns:
            User: Creates a bot which will be managed by another bot. Returns the created
                bot. May return an error with a message "BOT_CREATE_LIMIT_EXCEEDED" if the
                user already owns the maximum allowed number of bots as per
                getOption("owned_bot_count_max"). An internal link
                "https://t.me/BotFather?start=deletebot" can be processed to handle the
                error
        """
        request = functions.CreateBot(
            manager_bot_user_id=manager_bot_user_id,
            name=name,
            username=username,
            via_link=via_link,
        )
        result: User = await self._call(request, User)
        return result

