    async def get_chat_event_log(
        self,
        *,
        chat_id: int = 0,
        query: str = "",
        from_event_id: Int64 = Int64(0),
        limit: int = 0,
        filters: ChatEventLogFilters | None = None,
        user_ids: list[int] | None = None,
    ) -> ChatEvents:
        """Returns a list of service actions taken by chat members and administrators in the
        last 48 hours. Available only in supergroups and channels. Requires administrator
        rights. Returns results in reverse chronological order (i.e., in order of decreasing
        event_id)

        Args:
            chat_id: Chat identifier
            query: Search query by which to filter events
            from_event_id: Identifier of an event from which to return results. Use 0 to get
                results from the latest events
            limit: The maximum number of events to return; up to 100
            filters: The types of events to return; pass null to get chat events of all
                types
            user_ids: User identifiers by which to filter events. By default, events
                relating to all users will be returned

        Returns:
            ChatEvents: Returns a list of service actions taken by chat members and
                administrators in the last 48 hours. Available only in supergroups and
                channels. Requires administrator rights. Returns results in reverse
                chronological order (i.e., in order of decreasing event_id)
        """
        request = functions.GetChatEventLog(
            chat_id=chat_id,
            query=query,
            from_event_id=from_event_id,
            limit=limit,
            filters=filters,
            user_ids=user_ids or [],
        )
        result: ChatEvents = await self._call(request, ChatEvents)
        return result

