    async def search_gifts_for_resale(
        self,
        *,
        gift_id: Int64 = Int64(0),
        order: GiftForResaleOrder,
        for_crafting: bool = False,
        for_stars: bool = False,
        attributes: list[UpgradedGiftAttributeId] | None = None,
        offset: str = "",
        limit: int = 0,
    ) -> GiftsForResale:
        """Returns upgraded gifts that can be bought from other owners using sendResoldGift

        Args:
            gift_id: Identifier of the regular gift that was upgraded to a unique gift
            order: Order in which the results will be sorted
            for_crafting: Pass true to get only gifts suitable for crafting
            for_stars: Pass true to get only gifts that can be bought using Telegram Stars
            attributes: Attributes used to filter received gifts. If multiple attributes of
                the same type are specified, then all of them are allowed. If none
                attributes of specific type are specified, then all values for this
                attribute type are allowed
            offset: Offset of the first entry to return as received from the previous
                request with the same order and attributes; use empty string to get the
                first chunk of results
            limit: The maximum number of gifts to return

        Returns:
            GiftsForResale: Returns upgraded gifts that can be bought from other owners
                using sendResoldGift
        """
        request = functions.SearchGiftsForResale(
            gift_id=gift_id,
            order=order,
            for_crafting=for_crafting,
            for_stars=for_stars,
            attributes=attributes or [],
            offset=offset,
            limit=limit,
        )
        result: GiftsForResale = await self._call(request, GiftsForResale)
        return result

