    async def create_new_sticker_set(
        self,
        *,
        user_id: int = 0,
        title: str = "",
        name: str = "",
        sticker_type: StickerType,
        needs_repainting: bool = False,
        stickers: list[NewSticker] | None = None,
        source: str = "",
    ) -> StickerSet:
        """Creates a new sticker set. Returns the newly created sticker set

        Args:
            user_id: Sticker set owner; ignored for regular users
            title: Sticker set title; 1-64 characters
            name: Sticker set name. Can contain only English letters, digits and
                underscores. Must end with *"_by_<bot username>"* (*<bot_username>* is case
                insensitive) for bots; 0-64 characters. If empty, then the name returned by
                getSuggestedStickerSetName will be used automatically
            sticker_type: Type of the stickers in the set
            needs_repainting: Pass true if stickers in the sticker set must be repainted;
                for custom emoji sticker sets only
            stickers: List of stickers to be added to the set; 1-200 stickers for custom
                emoji sticker sets, and 1-120 stickers otherwise. For TGS stickers,
                uploadStickerFile must be used before the sticker is shown
            source: Source of the sticker set; may be empty if unknown

        Returns:
            StickerSet: Creates a new sticker set. Returns the newly created sticker set
        """
        request = functions.CreateNewStickerSet(
            user_id=user_id,
            title=title,
            name=name,
            sticker_type=sticker_type,
            needs_repainting=needs_repainting,
            stickers=stickers or [],
            source=source,
        )
        result: StickerSet = await self._call(request, StickerSet)
        return result

