class SyncMethods:
    """The 28 functions TDLib can run without a request queue.

    These need no client and no event loop, so they work before start-up.
    """

    def _execute(self, request: TDObject, result: Any) -> Any:
        """Run ``request`` in the calling thread and decode it as ``result``."""
        raise NotImplementedError

    def check_quick_reply_shortcut_name(
        self,
        *,
        name: str = "",
    ) -> Ok:
        """Checks validness of a name for a quick reply shortcut. Can be called synchronously

        Args:
            name: The name of the shortcut; 1-32 characters

        Returns:
            Ok: Checks validness of a name for a quick reply shortcut. Can be called
                synchronously
        """
        request = functions.CheckQuickReplyShortcutName(
            name=name,
        )
        result: Ok = self._execute(request, Ok)
        return result

    def search_quote(
        self,
        *,
        text: FormattedText,
        quote: FormattedText,
        quote_position: int = 0,
    ) -> FoundPosition:
        """Searches for a given quote in a text. Returns found quote start position in UTF-16
        code units. Returns a 404 error if the quote is not found. Can be called
        synchronously

        Args:
            text: Text in which to search for the quote
            quote: Quote to search for
            quote_position: Approximate quote position in UTF-16 code units

        Returns:
            FoundPosition: Searches for a given quote in a text. Returns found quote start
                position in UTF-16 code units. Returns a 404 error if the quote is not
                found. Can be called synchronously
        """
        request = functions.SearchQuote(
            text=text,
            quote=quote,
            quote_position=quote_position,
        )
        result: FoundPosition = self._execute(request, FoundPosition)
        return result

    def get_text_entities(
        self,
        *,
        text: str = "",
    ) -> TextEntities:
        """Returns all entities (mentions, hashtags, cashtags, bot commands, bank card numbers,
        URLs, and email addresses) found in the text. Can be called synchronously

        Args:
            text: The text in which to look for entities

        Returns:
            TextEntities: Returns all entities (mentions, hashtags, cashtags, bot commands,
                bank card numbers, URLs, and email addresses) found in the text. Can be
                called synchronously
        """
        request = functions.GetTextEntities(
            text=text,
        )
        result: TextEntities = self._execute(request, TextEntities)
        return result

    def parse_text_entities(
        self,
        *,
        text: str = "",
        parse_mode: TextParseMode,
    ) -> FormattedText:
        """Parses Bold, Italic, Underline, Strikethrough, Spoiler, CustomEmoji, BlockQuote,
        ExpandableBlockQuote, Code, Pre, PreCode, TextUrl, MentionName, and DateTime
        entities from a marked-up text. Can be called synchronously

        Args:
            text: The text to parse
            parse_mode: Text parse mode

        Returns:
            FormattedText: Parses Bold, Italic, Underline, Strikethrough, Spoiler,
                CustomEmoji, BlockQuote, ExpandableBlockQuote, Code, Pre, PreCode, TextUrl,
                MentionName, and DateTime entities from a marked-up text. Can be called
                synchronously
        """
        request = functions.ParseTextEntities(
            text=text,
            parse_mode=parse_mode,
        )
        result: FormattedText = self._execute(request, FormattedText)
        return result

    def parse_markdown(
        self,
        *,
        text: FormattedText,
    ) -> FormattedText:
        """Parses Markdown entities in a human-friendly format, ignoring markup errors. Can be
        called synchronously

        Args:
            text: The text to parse. For example, "__italic__ ~~strikethrough~~ ||spoiler||
                **bold** `code` ```pre``` __[italic__ text_url](telegram.org) __italic**bold
                italic__bold**"

        Returns:
            FormattedText: Parses Markdown entities in a human-friendly format, ignoring
                markup errors. Can be called synchronously
        """
        request = functions.ParseMarkdown(
            text=text,
        )
