    def search_strings_by_prefix(
        self,
        *,
        strings: list[str] | None = None,
        query: str = "",
        limit: int = 0,
        return_none_for_empty_query: bool = False,
    ) -> FoundPositions:
        """Searches specified query by word prefixes in the provided strings. Returns 0-based
        positions of strings that matched. Can be called synchronously

        Args:
            strings: The strings to search in for the query
            query: Query to search for
            limit: The maximum number of objects to return
            return_none_for_empty_query: Pass true to receive no results for an empty query

        Returns:
            FoundPositions: Searches specified query by word prefixes in the provided
                strings. Returns 0-based positions of strings that matched. Can be called
                synchronously
        """
        request = functions.SearchStringsByPrefix(
            strings=strings or [],
            query=query,
            limit=limit,
            return_none_for_empty_query=return_none_for_empty_query,
        )
        result: FoundPositions = self._execute(request, FoundPositions)
        return result

