    def set_log_verbosity_level(
        self,
        *,
        new_verbosity_level: int = 0,
    ) -> Ok:
        """Sets the verbosity level of the internal logging of TDLib. Can be called
        synchronously

        Args:
            new_verbosity_level: New value of the verbosity level for logging. Value 0
                corresponds to fatal errors, value 1 corresponds to errors, value 2
                corresponds to warnings and debug warnings, value 3 corresponds to
                informational, value 4 corresponds to debug, value 5 corresponds to verbose
                debug, value greater than 5 and up to 1023 can be used to enable even more
                logging

        Returns:
            Ok: Sets the verbosity level of the internal logging of TDLib. Can be called
                synchronously
        """
        request = functions.SetLogVerbosityLevel(
            new_verbosity_level=new_verbosity_level,
        )
        result: Ok = self._execute(request, Ok)
        return result

